rules:
- id: "vuln-forget-it-adf0c7fd"
  pattern: |
    $('#setForgetTime').change(function() {
      if (document.getElementById('setForgetTime').value > 0) {
        forgetitoptions.forget_save_options();
      } else {
        document.getElementById('setForgetTime').value = 1;
      }
    });
  pattern-not: |
    $('#setForgetTime').change(function() {
      if (document.getElementById('setForgetTime').value > 0) {
        forgetitoptions.forget_save_options();
      } else {
        document.getElementById('setForgetTime').value = 1;
      }
    });
  languages: ["javascript"]
  message: "Potential vulnerability in forget-it settings.js file detected. The code sets the forget time to a value less than 1 minute, which can cause a denial of service attack."
  severity: ERROR
  metadata:
    category: security
    cwe: CWE-79
    owasp: A3
